### Breadth-First Search (BFS)

BFS explores all the neighbors of a vertex before moving to the next level of vertices. It is particularly useful for graphs where the shortest path is the goal.

```python
from collections import deque

def bfs(graph, start, end):
    # Graph is represented as an adjacency list
    # Graph: {vertex: [neighbours]}
    # Example: {0: [1, 2], 1: [0, 3], 2: [0, 4], 3: [1, 5], 4: [2], 5: [3]}

    if start not in graph or end not in graph:
        return None

    queue = deque([start])
    visited = set([start])
    parent = {start: None}

    while queue:
        current = queue.popleft()

        if current == end:
            path = []
            while current is not None:
                path.insert(0, current)
                current = parent[current]
            return path

        for neighbor in graph[current]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
                parent[neighbor] = current

    return None

# Example usage:
graph = {
    0: [1, 2],
    1: [0, 3],
    2: [0, 4],
    3: [1, 5],
    4: [2],
    5: [3]
}

print(bfs(graph, 0, 4))  # Output: [0, 2, 4]
```

